powershell.exe -Command "@'
import subprocess,pathlib
nu=pathlib.Path('REFERENCE_BINARY.txt').read_text().strip()
p=subprocess.run([nu,'--no-config-file','-c','[1 2]'],capture_output=True)
print(p.stdout.hex())
for enc in ['utf-8','cp936','cp437','cp1252']:
 try: print(enc,repr(p.stdout.decode(enc)))
 except Exception as e: print(e)
'@ | python -"

